using System.Diagnostics;
using System.Reflection;
using System.Text.Json;
using System.Threading.Channels;
using AISwitcher.Core;

if(args.FirstOrDefault()=="--rpc-fixture") { await Fixture(args.ElementAtOrDefault(1)??"normal");return 0; }
var tests=new List<(string Name,Func<Task> Run)>();
void Test(string name,Action action)=>tests.Add((name,()=>{action();return Task.CompletedTask;}));
void AsyncTest(string name,Func<Task> action)=>tests.Add((name,action));
void Equal<T>(T actual,T expected){if(!EqualityComparer<T>.Default.Equals(actual,expected))throw new Exception($"Expected {expected}, got {actual}");}
void True(bool value,string message="Condition failed"){if(!value)throw new Exception(message);}
void Throws(Action action){try{action();}catch{return;}throw new Exception("Expected failure");}
async Task Fails(Func<Task> action){try{await action();}catch{return;}throw new Exception("Expected failure");}
var root=Path.Combine(Path.GetTempPath(),"ai-switcher-core-tests."+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
Repository Repo(string name)=>new(Path.Combine(root,name),Path.Combine(root,name+"-backend"));
Account Profile(string name="A",Agent agent=Agent.Chatgpt,LaunchMode mode=LaunchMode.Desktop)=>new(){Name=name,Agent=agent,LaunchMode=mode};
var now=DateTimeOffset.UtcNow;
Account WithQuota(string name,double used,double secondary=40,TimeSpan? age=null,long? reset=null){var limits=new Limits("identity",new("codex",null,new(used,300,reset??now.AddHours(2).ToUnixTimeSeconds()),new(secondary,10080,now.AddDays(3).ToUnixTimeSeconds())),null);return Profile(name)with{DesktopConnection=new(new("fixture@example.test","plus","identity"),new(limits,now-(age??TimeSpan.Zero)))};}
Test("Store executables and aliases are recognized without confusing sibling paths",()=>{True(WindowsExecutable.IsStorePath(@"C:\Program Files\WindowsApps\OpenAI.Codex_26\app\Codex.exe"));True(WindowsExecutable.IsStorePath(@"C:\Users\A\AppData\Local\Microsoft\WindowsApps\codex.exe"));True(!WindowsExecutable.IsStorePath(@"C:\Users\A\WindowsAppsBackup\codex.exe"));});
Test("Codex version output rejects GUI labels and unrelated executables",()=>{True(WindowsExecutable.IsCodexVersion("codex-cli 0.164.0\r\n"));True(WindowsExecutable.IsCodexVersion("codex-cli 0.150.0-alpha.8"));True(!WindowsExecutable.IsCodexVersion("Codex 26.1021"));True(!WindowsExecutable.IsCodexVersion("not codex-cli 0.164.0"));});
Test("PE inspection distinguishes GUI, console, corrupt and non-PE files before execution",()=>{var path=Path.Combine(root,"test.exe");var data=new byte[200];data[0]=77;data[1]=90;System.Buffers.Binary.BinaryPrimitives.WriteInt32LittleEndian(data.AsSpan(60),64);data[64]=80;data[65]=69;data[88]=0x0b;data[89]=2;data[156]=2;File.WriteAllBytes(path,data);True(!WindowsExecutable.IsConsole(path));data[156]=3;File.WriteAllBytes(path,data);True(WindowsExecutable.IsConsole(path));data[60]=250;File.WriteAllBytes(path,data);True(!WindowsExecutable.IsConsole(path));File.WriteAllText(path,"#!/bin/sh\nexit 0");True(!WindowsExecutable.IsConsole(path));});
AsyncTest("Store runtime copies program bytes, keeps account data outside, reuses one cache and survives profile deletion",async()=>{var repo=Repo("runtime-copy");var src=Path.Combine(root,"store-program","app");Directory.CreateDirectory(Path.Combine(src,"resources"));var source=Path.Combine(src,"ChatGPT.exe");File.WriteAllText(source,"program-bytes");File.WriteAllText(Path.Combine(src,"resources","app.asar"),"archive-bytes");File.WriteAllText(Path.Combine(root,"store-program","auth.json"),"must-not-copy");var a=Profile();repo.Save(new(){Accounts=[a]});repo.PrepareProfile(a);var copied=await StoreRuntime.PrepareAsync(repo.Root,source);Equal(File.ReadAllText(copied),"program-bytes");True(!File.Exists(Path.Combine(Path.GetDirectoryName(copied)!,"auth.json")));True(StoreRuntime.IsManagedExecutable(repo.Root,copied));True(!StoreRuntime.IsManagedExecutable(Repo("other-runtime").Root,copied));var result=await Task.WhenAll(StoreRuntime.PrepareAsync(repo.Root,source),StoreRuntime.PrepareAsync(repo.Root,source));True(result.All(x=>x==copied));repo.Remove(a,repo.Load());True(File.Exists(copied));True(File.Exists(source));});
AsyncTest("Store runtime rejects critical-file corruption and preserves unowned cache directories",async()=>{var repo=Repo("runtime-integrity");var src=Path.Combine(root,"store-integrity","app");Directory.CreateDirectory(Path.Combine(src,"resources"));var source=Path.Combine(src,"ChatGPT.exe");File.WriteAllText(source,"program");File.WriteAllText(Path.Combine(src,"resources","app.asar"),"archive");var copied=await StoreRuntime.PrepareAsync(repo.Root,source);File.WriteAllText(copied,"changed");await Fails(()=>StoreRuntime.PrepareAsync(repo.Root,source));Equal(File.ReadAllText(copied),"changed");var other=Repo("runtime-unowned");var cache=StoreRuntime.DirectoryFor(other.Root,source);Directory.CreateDirectory(cache);File.WriteAllText(Path.Combine(cache,"keep"),"untouched");await Fails(()=>StoreRuntime.PrepareAsync(other.Root,source));Equal(File.ReadAllText(Path.Combine(cache,"keep")),"untouched");});
AsyncTest("Store runtime rejects source links and interrupted preparation leaves no published cache",async()=>{var repo=Repo("runtime-link");var src=Path.Combine(root,"store-link","app");Directory.CreateDirectory(Path.Combine(src,"resources"));var source=Path.Combine(src,"ChatGPT.exe");File.WriteAllText(source,"program");File.WriteAllText(Path.Combine(src,"resources","app.asar"),"archive");var privateFile=Path.Combine(root,"private-token");File.WriteAllText(privateFile,"not-program-data");File.CreateSymbolicLink(Path.Combine(src,"bad-link"),privateFile);await Fails(()=>StoreRuntime.PrepareAsync(repo.Root,source));True(!Directory.Exists(StoreRuntime.DirectoryFor(repo.Root,source)));True(!Directory.EnumerateDirectories(Path.Combine(repo.Root,"Runtimes","chatgpt")).Any());Equal(File.ReadAllText(privateFile),"not-program-data");});
Test("All seven themes and palettes persist independently",()=>{Equal(Themes.All.Count,7);foreach(var theme in Themes.All){var repo=Repo("theme-"+theme.Id);var prefs=new Preferences{Theme=theme.Id,Language="en"};repo.SavePreferences(prefs);Equal(repo.LoadPreferences().Theme,theme.Id);}Equal(Themes.Get("terminalBlack").Canvas,"#000000");Equal(Themes.Get("terminal").Canvas,"#090E0B");});
Test("English and Vietnamese catalogs and placeholders have parity",()=>{var en=Assets.Read<Dictionary<string,string>>("en.json");var vi=Assets.Read<Dictionary<string,string>>("vi.json");Equal(en.Count,vi.Count);foreach(var key in en.Keys){True(vi.ContainsKey(key));Equal(System.Text.RegularExpressions.Regex.Matches(en[key],"%@|%%").Count,System.Text.RegularExpressions.Regex.Matches(vi[key],"%@|%%").Count);}Equal(new Localizer("vi")["Add account"],"Thêm tài khoản");});
Test("Formatting does not reinterpret profile text",()=>{var l=new Localizer("en");Equal(l.Format("Opened %@","50% %@"),"Opened 50% %@");Equal(l.Format("%@%% remaining","77"),"77% remaining");});
Test("Invalid independent settings fall back without discarding valid theme",()=>{var prefs=new Preferences{Theme="terminalBlack",Language="bad",QuotaSortKey=(SortKey)999,AgentFilter=(Agent)999};prefs.Normalize();Equal(prefs.Language,"vi");Equal(prefs.Theme,"terminalBlack");Equal(prefs.QuotaSortKey,SortKey.Name);Equal(prefs.AgentFilter,null);});
Test("Turning quota-only off always returns to cards",()=>{var prefs=new Preferences{WorkspaceLayout=WorkspaceLayout.QuotaTable};prefs.SetQuotaOnly(false);Equal(prefs.WorkspaceLayout,WorkspaceLayout.Cards);prefs.SetQuotaOnly(true);Equal(prefs.WorkspaceLayout,WorkspaceLayout.QuotaTable);prefs.SetQuotaOnly(false);Equal(prefs.WorkspaceLayout,WorkspaceLayout.Cards);});
Test("All agent capabilities are distinct and non-ChatGPT cached quota stays hidden",()=>{foreach(var agent in Enum.GetValues<Agent>()){var a=WithQuota("Provider",20)with{Agent=agent};Equal(a.Connection!=null,agent==Agent.Chatgpt);Equal(a.UsesCodexDesktop,agent==Agent.Chatgpt);True(a.Agent.Url().Scheme=="https");}Equal(Profile(agent:Agent.Gemini).EffectiveMode,LaunchMode.Browser);Equal(Profile(agent:Agent.Claude).EffectiveMode,LaunchMode.Desktop);});
Test("Profiles, quota, and recent state survive reload",()=>{var repo=Repo("roundtrip");var a=WithQuota("Work",23);var snapshot=new Snapshot{Accounts=[a],LastOpenedId=a.Id};repo.Save(snapshot);var loaded=repo.Load();Equal(loaded.Accounts[0].Name,a.Name);Equal(loaded.Accounts[0].Connection!.Quota!.Limits.Buckets.First().Value.Primary!.Remaining,77d);Equal(loaded.LastOpenedId,a.Id);});
Test("Empty load does not invent metadata",()=>{var repo=Repo("empty");Equal(repo.Load().Accounts.Count,0);True(!File.Exists(repo.MetadataPath));});
Test("Corrupt and future metadata are preserved",()=>{var repo=Repo("corrupt");Directory.CreateDirectory(repo.Root);File.WriteAllText(repo.MetadataPath,"{bad");Throws(()=>repo.Load());Equal(File.ReadAllText(repo.MetadataPath),"{bad");File.WriteAllText(repo.MetadataPath,"{\"version\":999,\"accounts\":[]}");Throws(()=>repo.Load());True(File.ReadAllText(repo.MetadataPath).Contains("999"));});
Test("Duplicate IDs and duplicate shared launchers are rejected",()=>{var a=Profile();Throws(()=>new Snapshot{Accounts=[a,a]}.Validate());Throws(()=>new Snapshot{Accounts=[Profile(agent:Agent.Antigravity),Profile(agent:Agent.Antigravity)]}.Validate());});
Test("Account names do not control storage paths",()=>{var repo=Repo("names");var a=Profile("../../external");repo.PrepareProfile(a);True(repo.DataPath(a).StartsWith(repo.Root));True(repo.ProfilePath(a).Contains(a.Id.ToString()));});
Test("Process and config homes remain distinct per ID and data root",()=>{var one=Repo("one");var two=Repo("two");var a=Profile();var b=Profile();True(one.DataPath(a)!=one.DataPath(b));True(one.BackendPath(a.Id)!=one.BackendPath(b.Id));True(one.BackendPath(a.Id)!=two.BackendPath(a.Id));});
