Test("Inherited keys and runtime overrides do not reach child processes",()=>{var env=ChildEnvironment.Create(new Dictionary<string,string>{{"SystemRoot","C:/Windows"},{"PATH","path"},{"ANTHROPIC_API_KEY","secret"},{"OPENAI_API_KEY","secret"},{"CODEX_HOME","wrong"},{"NODE_OPTIONS","bad"},{"CLAUDE_CODE_OAUTH_TOKEN","secret"}},"profile");Equal(env.Count,3);Equal(env["CODEX_HOME"],"profile");True(!env.ContainsKey("NODE_OPTIONS"));});
