Test("Remaining quota clamps finite values and preserves unknowns",()=>{Equal(new QuotaWindow(125,300,null).Remaining,0d);Equal(new QuotaWindow(-3,300,null).Remaining,100d);Equal(new QuotaWindow(double.NaN,300,null).Remaining,null);});
Test("Expired limits cannot fabricate quota or future reset",()=>{var a=WithQuota("expired",90,reset:now.AddSeconds(-1).ToUnixTimeSeconds());True(a.Connection!.Quota!.IsStale(now));True(a.Connection.Quota.Limits.Buckets.First().Value.Primary!.Expired(now));});
Test("Quota sort keeps missing, stale and failed values last in both directions",()=>{var low=WithQuota("low",90);var high=WithQuota("high",10);var stale=WithQuota("stale",99,age:TimeSpan.FromHours(1));var missing=Profile("missing");foreach(var ascending in new[]{true,false}){var sorted=QuotaOverview.Sort([missing,stale,high,low],new(){QuotaSortKey=SortKey.PrimaryRemaining,QuotaSortAscending=ascending},time:now).ToArray();Equal(sorted[0].Id,ascending?low.Id:high.Id);True(sorted.Take(2).All(x=>x.Id!=stale.Id&&x.Id!=missing.Id));}});
Test("Multiple quota buckets remain separate and prefer codex",()=>{var limits=new Limits(null,null,new(){["other"]=new("other",null,new(90,300,null),null),["codex"]=new("codex",null,new(20,300,null),null)});Equal(limits.Buckets.Count(),2);Equal(limits.Buckets.First().Key,"codex");});
Test("Low alerts deduplicate and recovery requires an observed fresh crossing",()=>{var prefs=new Preferences{AlertsEnabled=true,AlertThreshold=20};var a=WithQuota("alert",85);Equal(AlertTracker.Evaluate(a,prefs,now).Count(x=>!x.Recovered),1);Equal(AlertTracker.Evaluate(a,prefs,now).Count,0);var b=WithQuota("alert",10)with{Id=a.Id};Equal(AlertTracker.Evaluate(b,prefs,now).Count(x=>x.Recovered),1);Equal(AlertTracker.Evaluate(b,prefs,now).Count,0);});
Test("Stale quota and disabled alerts do not change baselines",()=>{var prefs=new Preferences{AlertsEnabled=true};var a=WithQuota("stale",90,age:TimeSpan.FromHours(1));Equal(AlertTracker.Evaluate(a,prefs,now).Count,0);Equal(prefs.AlertObservations.Count,0);prefs.AlertsEnabled=false;Equal(AlertTracker.Evaluate(WithQuota("off",95),prefs,now).Count,0);});
Test("Identity change cannot invent recovery",()=>{var prefs=new Preferences{AlertsEnabled=true};var a=WithQuota("old",90);AlertTracker.Evaluate(a,prefs,now);var fresh=WithQuota("new",10)with{Id=a.Id};fresh=fresh with{DesktopConnection=fresh.DesktopConnection! with{Identity=new("another@example.test","plus","another")}};Equal(AlertTracker.Evaluate(fresh,prefs,now).Count,0);});
RpcClient Client(string mode,TimeSpan? timeout=null){var dir=Path.Combine(root,"rpc-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);var executable=Path.Combine(Path.GetFullPath(Path.Combine(System.Runtime.InteropServices.RuntimeEnvironment.GetRuntimeDirectory(),"..","..","..")),OperatingSystem.IsWindows()?"dotnet.exe":"dotnet");List<string> argv=[Assembly.GetExecutingAssembly().Location];argv.AddRange(["--rpc-fixture",mode]);var env=ChildEnvironment.Create(Environment.GetEnvironmentVariables().Cast<System.Collections.DictionaryEntry>().ToDictionary(x=>(string)x.Key,x=>(string)x.Value!),dir);var info=ChildEnvironment.StartInfo(executable,argv,env,dir);return new(new StdioTransport(info),timeout);}
AsyncTest("Real stdio accepts fragmented single-line JSON and verifies identity twice",async()=>{await using var client=Client("fragmented");await client.StartAsync();var value=await client.ReadQuotaAsync();Equal(value.Identity.Email,"fixture@example.test");Equal(value.Quota!.Limits.Buckets.First().Value.Primary!.Remaining,77d);});
AsyncTest("Early login notification is retained until its waiter exists",async()=>{await using var client=Client("login");await client.StartAsync();var login=await client.StartLoginAsync();await client.WaitForLoginAsync(login.Id);Equal(login.Url.Host,"auth.openai.com");});
AsyncTest("Signed-out session cannot return another identity",async()=>{await using var client=Client("unauthed");await client.StartAsync();await Fails(()=>client.ReadIdentityAsync());});
AsyncTest("Identity switching during quota read is rejected",async()=>{await using var client=Client("change");await client.StartAsync();await Fails(()=>client.ReadQuotaAsync());});
AsyncTest("Request timeout completes without hanging",async()=>{await using var client=Client("timeout",TimeSpan.FromSeconds(2));await client.StartAsync();await Fails(()=>client.ReadQuotaAsync());});
AsyncTest("Cancellation completes pending requests",async()=>{await using var client=Client("timeout");await client.StartAsync();using var ct=new CancellationTokenSource(50);await Fails(()=>client.ReadQuotaAsync(ct.Token));});
AsyncTest("Raw RPC errors never reach user messages",async()=>{await using var client=Client("error");await client.StartAsync();try{await client.ReadQuotaAsync();throw new Exception("Expected RPC failure");}catch(AppError error){True(!error.Message.Contains("private-detail"));}});
AsyncTest("Process exit completes pending requests",async()=>{await using var client=Client("exit");await client.StartAsync();await Fails(()=>client.ReadQuotaAsync());});
var failures=0;try{foreach(var test in tests){try{await test.Run();Console.WriteLine("PASS "+test.Name);}catch(Exception e){failures++;Console.Error.WriteLine("FAIL "+test.Name+": "+e);}}}finally{Repository.DeleteTree(root);}Console.WriteLine($"{tests.Count-failures}/{tests.Count} tests passed");return failures==0?0:1;

static async Task Fixture(string mode){int identities=0;while(await Console.In.ReadLineAsync() is string line){var data=JsonDocument.Parse(line).RootElement;var method=data.GetProperty("method").GetString();if(!data.TryGetProperty("id",out var id))continue;object? result=new{};
    if(method=="account/read"){identities++;result=new{account=mode=="unauthed"?null:new{type="chatgpt",email=mode=="change"&&identities>1?"changed@example.test":"fixture@example.test",planType="plus"}};}
    if(method=="account/rateLimits/read"){if(mode=="timeout")continue;if(mode=="exit")return;if(mode=="error"){Console.WriteLine(JsonSerializer.Serialize(new{id=id.GetInt32(),error=new{code=-32001,message="private-detail-do-not-display"}}));continue;}result=new{rateLimits=new{primary=new{usedPercent=23,windowDurationMins=300,resetsAt=2000000000}}};}
    if(method=="account/login/start"){Console.WriteLine(JsonSerializer.Serialize(new{method="account/login/completed",@params=new{loginId="fixture",success=true}}));result=new{loginId="fixture",authUrl="https://auth.openai.com/fixture"};}
    var output=JsonSerializer.Serialize(new{id=id.GetInt32(),result});if(mode=="fragmented"){for(var i=0;i<output.Length;i+=7){Console.Write(output.Substring(i,Math.Min(7,output.Length-i)));await Console.Out.FlushAsync();await Task.Delay(1);}Console.WriteLine();}else Console.WriteLine(output);
}}
